  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Keyframes based on 3-second timeline
  const fadeEndFrame = 1.2 * fps;
  const countEndFrame = 2.2 * fps;
  const arrowStartFrame = 2.2 * fps;
  const endFrame = durationInSeconds * fps;

  // Scene 1: Fade in (0 - 1.2s)
  const introOpacity = interpolate(frame, [0, fadeEndFrame], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Scene 2: Percentage Increase (1.2s - 2.2s)
  const currentPercentage = Math.round(
    interpolate(
      frame,
      [fadeEndFrame, countEndFrame],
      [startPercentage, endPercentage],
      {
        easing: Easing.inOut(Easing.cubic),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    )
  );

  // Scene 3: Arrow appears & scales up (2.2s - 3.0s)
  const arrowPopScale = spring({
    fps,
    frame: frame - arrowStartFrame,
    config: {
      damping: 14,
      stiffness: 120,
    },
  });

